transportPayloadTypeConfiguration.deviceTelemetryProtoSchema:
// blg20.proto — the satellite-safe uplink, SPEC §19.
//
// THE FIELD NUMBERS ARE THE CBOR KEYS. That is the whole design of §07 D2: one set of numbers,
// two wire formats, and a consumer that has decoded either one holds the same fields. encode_pb.c
// writes these numbers as protobuf tags; encode_cbor.c writes the same numbers as CBOR map keys.
// If a number changes here it must change in both encoders and in the host rig, and the rig will
// say so — tools/test_encoders.py decodes the protobuf side straight out of THIS file.
//
// Append only. Never renumber: a gateway in the field encodes with the table it was built
// against and there is no way to ask it which that was (record.h says the same thing about the
// record keys, and for the same reason).
//
// ── Three things this file is NOT ────────────────────────────────────────────────────────────
//
// 1. It is not generated/05-data-plane/record.proto. That file is the shape ThingsBoard's HOSTED
//    CoAP transport demands — `optional int64 ts = 1; Values values = 2;`, one record per POST,
//    validated by DeviceProfileDataValidator. This file is §19's Uplink envelope, which that
//    validator will refuse (its top-level message is not {ts, values}). The two are different
//    contracts for different consumers and both are real. See F-M3-7.
//
// 2. It is not fed to nanopb in this build. `protoc` is absent on the authoring host, so the
//    generator could not run; encode_pb.c is a hand-written writer against these numbers, and the
//    host rig proves its bytes decode in a standard protobuf parser driven by this file. See
//    F-M3-3 for the generator command and the NCS check.
//
// 3. It carries no options, no imports and no `required`. ThingsBoard's schema validator refuses
//    a profile containing any of them, and a schema that cannot also be pasted into a device
//    profile is a schema with one fewer use.

syntax = "proto3";

package blg20;

// One alert, as §09 defines it. Ten bytes is the budget; the short id (dev) is what buys it —
// two bytes instead of a six-byte address, which is the difference between eight alerts in a
// datagram and three.
message Alert {
	// ── FIELD 1 IS RETIRED. NEVER REUSE IT. ─────────────────────────────────────────────
	//
	// It was `uint32 seq`, the gateway sequence repeated on every alert. It went on 13 Sep
	// 2026 because `Uplink.gw_seq` already stamps the datagram and an alert's position in
	// the repeated field already orders it inside one — so the field was three bytes an
	// alert to say twice what the envelope said once, and three bytes an alert is the
	// difference between one alert and two in a 128-byte satellite datagram (F-M3-19).
	//
	// WHY THERE IS NO `reserved 1;` HERE, WHICH IS WHAT YOU WOULD EXPECT. ThingsBoard's
	// DynamicProtoUtils.validateProtoSchema refuses a device-profile schema that declares a
	// reserved range at all — read out of the platform's source and written up in
	// generated/05-data-plane/record.proto. The keyword that protects the number would cost
	// the profile the transport needs. So the number is protected by this comment and by a
	// check in tools/test_encoders.py, which fails if any message ever declares a field 1
	// in Alert.
	uint32 dev    = 2;   // 16-bit short id; the device table resolves it, never the datagram
	uint32 rule   = 3;
	sint32 value  = 4;   // scaled per rule. sint32, not int32: a negative int32 varint is ten
			     // bytes, and the values that alert are as often below a threshold as above
	uint32 sev    = 5;
	uint32 flags  = 6;   // bit0 enter, bit1 exit, bit2 latched
	uint32 age_s  = 7;   // age at the moment of transmission, not an absolute time: on satellite
			     // the attach alone can be four minutes and the datagram is stamped at send
}

// One status per window. §09: "nothing to report" must still be reported, cheaply, so that
// silence means a fault.
message Status {
	uint32 win             = 1;
	uint32 seen            = 2;
	uint32 expected        = 3;
	uint32 missing         = 4;
	repeated uint32 missing_ids = 5;   // the first few short ids, only when the datagram has room
	uint32 alerts_active   = 6;
	uint32 alerts_deferred = 7;
	uint32 batt_low        = 8;
	uint32 store_depth     = 9;
	uint32 dropped         = 10;
	uint32 quota_pct       = 11;
	uint32 bearer          = 12;
	sint32 rsrp            = 13;
	uint32 uptime_s        = 14;
	uint32 reset_cause     = 15;
	uint32 flags           = 16;       // bit0 time_unsynced, bit1 config_on_test
}

// One field of a digest: the per-field count / min / max / last that §09 calls the digest product.
message Field {
	uint32 id   = 1;
	uint32 n    = 2;
	sint32 min  = 3;
	sint32 max  = 4;
	sint32 last = 5;
	sint32 sum  = 6;
}

// One device over one window.
message Digest {
	uint32 dev          = 1;
	uint32 win          = 2;
	repeated Field f    = 3;
	uint32 seen         = 4;
	sint32 rssi_mean    = 5;
	uint32 batt         = 6;
}

// The daily health record (SPEC 10, "Diagnostics from a desk").
//
// "Per day on terrestrial: bearer transitions and their reasons, attach durations, socket errors,
// admission drops per device, session outcomes, modem temperature (%XTEMP), watchdog and fault
// counts, storage wear | ~200 B per day; withheld on satellite unless requested."
//
// EVERY FIELD IS A DELTA OVER THE WINDOW, not a lifetime total, with two exceptions that are
// marked: erase_cycles and boots, which are lifetime facts about the hardware and are the numbers
// a fleet plans replacements against. A delta is what a daily record is for — "eleven attaches
// yesterday, worst one 94 seconds" is actionable and "4,182 attaches since the unit was built" is
// not — and a counter that a reboot resets would otherwise send a negative day.
//
// WHY reason_n IS A REPEATED SCALAR AND NOT A MAP. proto3 maps are a synthetic nested message per
// entry and ThingsBoard's schema validator refuses several of the constructs they need; a packed
// repeated uint32 indexed by enum bearer_reason costs one tag, one length and one byte per
// non-trivial count. The index IS the reason, which is a closed set on both chips (bearer.h), so
// the two cannot drift without the build breaking.
message Health {
	uint32 day             = 1;   // days since the unix epoch. The window this record covers
	uint32 window_s        = 2;   // how long it actually spans; a unit that rebooted sends less
	                              // than a day and must not be read as if it sent one

	// The bearer, which is where almost every field failure on this product shows up first.
	uint32 transitions     = 3;
	repeated uint32 reason_n = 4; // indexed by enum bearer_reason; trailing zeroes trimmed
	uint32 attaches        = 5;   // successful ones
	uint32 attach_min_s    = 6;
	uint32 attach_avg_s    = 7;
	uint32 attach_max_s    = 8;
	uint32 sock_errors     = 9;
	uint32 modem_reinits   = 10;  // the modem watchdog fired and reinitialised the library
	sint32 modem_temp_c    = 11;  // %XTEMP, last read
	sint32 modem_temp_max  = 12;

	// The BLE half's, over FRAME_HEALTH. Nothing here is computed on this chip.
	uint32 admission_drops = 13;
	uint32 sess_ok         = 14;
	uint32 sess_partial    = 15;
	uint32 sess_refused    = 16;
	uint32 sess_timeout    = 17;

	// Self-protection and wear.
	uint32 wdt_resets      = 18;
	uint32 faults          = 19;
	uint32 boots           = 20;  // LIFETIME
	uint32 erase_cycles    = 21;  // LIFETIME. SPEC 10: "reported yearly in the health record"
	uint32 store_dropped   = 22;  // retired by the retention policy over the window
	uint32 store_depth     = 23;  // records held at the moment the record was built
	uint32 uptime_s        = 24;  // of the cellular half

	// The evaluation cap's counters. APPENDED, never inserted, and written only by an
	// evaluation image: a production unit sends none of them and the message it sends is the
	// message it always sent. A reader that does not know these three sees unknown fields,
	// which is what proto3 is for.
	uint32 demo_win_s      = 25;  // bearer-up seconds spent in the window that has just ended
	uint32 demo_total_s    = 26;  // LIFETIME bearer-up seconds against the allowance
	uint32 demo_rearm_s    = 27;  // seconds until the window re-arms; 0 = armed
}

// One datagram's body. NOT the top-level message any more — see Telemetry at the foot of this
// file, which is what actually goes on the wire and which is declared last for the reason this
// comment used to give.
message Uplink {
	// NOT WRITTEN WHEN THIS BODY IS WRAPPED IN `Telemetry` — which, since 13 Sep 2026, is
	// every protobuf datagram: `Telemetry.ts` carries the same value and carrying it twice
	// cost seven bytes of a satellite payload (F-M3-18). It is still written by an
	// unwrapped body, and the CBOR form (key 1) always carries it, because CBOR has no
	// envelope. A proto3 decoder reads the absent field back as 0, so both shapes decode.
	uint64 ts_ms            = 1;
	uint32 gw_seq           = 2;

	// SPEC §19 names this field `class`. It is `cls` here for exactly the reason
	// link_proto.h gives for `struct cfg_dpl.cls`: this schema is read by C and C++ tooling
	// and by a nanopb generator that will emit the name verbatim into a struct. The NUMBER
	// is the contract and the number is unchanged; the CBOR side carries the same 3 under the
	// same name (encode.h, UPF_CLASS). See F-M3-4.
	uint32 cls              = 3;

	repeated Status status  = 4;
	repeated Alert  alert   = 5;
	repeated Digest digest  = 6;

	// The raw records, as the CBOR array record.c already emits — key for key, byte for byte.
	//
	// Why a blob and not `repeated Digest`: the digest engine is M4. Until it exists the thing
	// the gateway actually holds is a BM20 digest record, and there is exactly one encoder for
	// it in this product (record.c) which is already the reference for the ThingsBoard CBOR
	// converter and for tests/record/digest.golden.hex. Wrapping those bytes keeps ONE record
	// encoder rather than a second one that can drift; M4 replaces this field with `digest`
	// and the field number stays reserved either way.
	bytes raw_cbor          = 7;

	// M6. Once a day, on a terrestrial window, and NEVER on satellite unless it is asked for
	// (SPEC 10). It rides the same datagram as everything else rather than costing one of its
	// own, which is the same rule the status and the alerts follow.
	Health health           = 8;
}

// ── The envelope the hosted transport insists on ─────────────────────────────────────────────
//
// ThingsBoard's DeviceProfileDataValidator.validateTelemetryDynamicMessageFields refuses a
// telemetry schema whose top-level message is not EXACTLY `optional int64 ts` plus a message
// field named `values` — measured against a live tenant on 11 September 2026 and written up in
// generated/05-data-plane/record.proto. `Uplink` is not that shape and never will be, so it is
// wrapped rather than bent: the datagram body is unchanged, and this is the two-field lid the
// platform's validator is looking for.
//
// `optional` on ts is mandatory, not stylistic — the validator names it in the refusal
// ("Field 'ts' should have optional keyword!"), and in proto3 it also makes the field a member
// of a synthetic oneof, which is what keeps an unset ts out of the JSON the platform prints.
//
// Set ts ONLY to a real unix epoch in milliseconds. parseWithTs takes the value verbatim, so a
// device uptime here files the sample in January 1970. Left out, the platform stamps arrival.
//
// DECLARED LAST, on purpose: DynamicProtoUtils.getDynamicMessageBuilder reduces the file's
// top-level types to the last one, so this rule cannot pick the wrong message.
message Telemetry {
	optional int64 ts = 1;
	Uplink values     = 2;
}

transportPayloadTypeConfiguration.deviceAttributesProtoSchema:
syntax = "proto3";
package attributes;
message Attributes {
  string devTable = 1;
  string rules = 2;
}

transportPayloadTypeConfiguration.deviceRpcRequestProtoSchema:
syntax = "proto3";
package rpc;
message RpcRequestMsg {
  optional string method = 1;
  optional int32 requestId = 2;
  optional string params = 3;
}

transportPayloadTypeConfiguration.deviceRpcResponseProtoSchema:
syntax = "proto3";
package rpc;
message RpcResponseMsg {
  optional string payload = 1;
}
